mapper.select:
WITH eligible AS ( SELECT d.theme_id,d.theme_week_start,tv.title,tv.intro_image_uri,a.mission_id,mv.title mission_title, d.attempt_id,left(coalesce(ans.plain_text,''),500) answer_excerpt, d.embedding_model=#{model} matching_model, CASE WHEN d.embedding_model=#{model} THEN 1-(d.embedding <=> CAST(#{vector} AS vector)) ELSE 0.0 END score, (0 + CASE WHEN d.content_text ILIKE #{keyword} ESCAPE '!' THEN 1 ELSE 0 END ) keyword_count FROM memory_search_doc d JOIN attempt a ON a.id=d.attempt_id JOIN theme_frame f ON f.student_id=d.student_id AND f.theme_id=d.theme_id AND f.theme_week_start=d.theme_week_start JOIN weekly_theme_version tv ON tv.id=f.theme_version_id JOIN mission_version mv ON mv.id=a.mission_version_id JOIN LATERAL (SELECT plain_text FROM answer WHERE attempt_id=a.id ORDER BY version DESC LIMIT 1) ans ON true WHERE d.student_id=#{studentId} AND a.student_id=d.student_id AND d.theme_week_start<#{before} AND d.status='READY' AND a.context IN ('THEME_DAY','THEME_REVIEW') AND a.completed_at IS NOT NULL
AND d.theme_week_start < #{to} AND d.theme_week_start + 7 > #{from}
), vector_ranks AS ( SELECT attempt_id,row_number() OVER (ORDER BY score DESC,theme_week_start DESC,theme_id,attempt_id) rank FROM eligible WHERE matching_model AND score>=#{minimum} ), keyword_ranks AS ( SELECT attempt_id,row_number() OVER (ORDER BY keyword_count DESC,theme_week_start DESC,theme_id,attempt_id) rank FROM eligible WHERE keyword_count>0 ), fused AS ( SELECT e.*,coalesce(1.0/(60+v.rank),0)+coalesce(1.0/(60+k.rank),0) rrf FROM eligible e LEFT JOIN vector_ranks v USING(attempt_id) LEFT JOIN keyword_ranks k USING(attempt_id) WHERE v.rank IS NOT NULL OR k.rank IS NOT NULL ), rounds AS ( SELECT theme_id,theme_week_start,max(rrf) rrf FROM fused GROUP BY theme_id,theme_week_start ORDER BY rrf DESC,theme_week_start DESC,theme_id LIMIT 3 ) SELECT h.* FROM fused h JOIN rounds r USING(theme_id,theme_week_start) ORDER BY r.rrf DESC,h.theme_week_start DESC,h.theme_id,h.rrf DESC,h.attempt_id
